head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/digital_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF71005_P.xml";
scwin.vMode = ""; //신규,수정 구분
scwin.vBzProcsNo = ""; //업무처리번호
scwin.procJob;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 * 공통코드 조회
 */
scwin.fn_searchCode = function() {
    dts_CHRG_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=CHRG_TP_CD";
    dts_CHRG_TP_CD.Reset();
    var strCbd = "",
        j;
    for (j = 1; j <= dts_CHRG_TP_CD.getTotalRow(); j++) {
        var val = dts_CHRG_TP_CD.getCellData(j, "VALUE");
        if (val.charAt(0) == "D") {
            strCbd = strCbd + (strCbd == "" ? "" : ",") + val + "^" + dts_CHRG_TP_CD.getCellData(j, "TEXT");
        }
    }
    cmb_CHRG_TP_CD.CBData = strCbd;

    //인덱스 첫번째로
    cmb_CHRG_TP_CD.setSelectedIndex(0);
    scwin.fn_setChrgNM();
};
scwin.fn_setChrgNM = function() {
    //담당자 리스트 조회 
    var url = "/digital/DigitalSupport.do";
    url += "?method=corpDisclsChrgList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&CHRG_TP_CD=" + $c.stf.getObjectValue(cmb_CHRG_TP_CD);
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_CHRG_NM.DataID = encodeURI(url);
    dts_CHRG_NM.Reset();
    var charNm = dts_Item.getCellData(1, "CHRG_NM");
    var strCbd = "",
        j;
    for (j = 1; j <= dts_CHRG_NM.getTotalRow(); j++) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_CHRG_NM.getCellData(j, "CHRG_NM") + "^" + dts_CHRG_NM.getCellData(j, "CHRG_NM");
    }
    if (strCbd) {
        cmb_CHRG_NM.CBData = strCbd;
    } else {
        cmb_CHRG_NM.CBData = "^ ";
    }

    //인덱스 셋팅
    if (charNm) cmb_CHRG_NM.BindColVal = charNm;

    else cmb_CHRG_NM.setSelectedIndex(0);
};
scwin.fn_list_sync = function() {
    var url = "/digital/DigitalSupport.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=digitalEduCompltList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&ISUR_CD=";
    url += "&CHRG_NM=";
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.setButton = function() {
    if (scwin.vMode == "I") {
        //저장일 경우 
        //저장 -> 활성화
        btn_save.src = "../img/btn_save.gif";
        btn_save.setDisabled(false);

        //수정 -> 비활성화
        btn_modify.src = "../img/btn_modify_d.gif";
        btn_modify.setDisabled(true);

        //삭제 -> 비활성화
        btn_delete.src = "../img/btn_delete_d.gif";
        btn_delete.setDisabled(true);
    } else if (scwin.vMode == "U") {
        //수정일경우
        //저장 -> 비활성화
        btn_save.src = "../img/btn_save_d.gif";
        btn_save.setDisabled(true);

        //수정 -> 활성화
        btn_modify.src = "../img/btn_modify.gif";
        btn_modify.setDisabled(false);

        //삭제 -> 활성화
        btn_delete.src = "../img/btn_delete.gif";
        btn_delete.setDisabled(false);
    }
};



/**
 * 저장버튼 클릭
 */
scwin.fn_save = function() {
    if (scwin.fn_validation()) {
        if (!$c.lcd.fn_isProcess(scwin.vMode)) return;

        //데이터 셋팅 
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo); //업무처리번호 새로 지정
        var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
        var CHRG_TP_CD = $c.stf.getObjectValue(cmb_CHRG_TP_CD);
        var CHRG_NM = $c.stf.getObjectValue(cmb_CHRG_NM);
        var EDU_DD = $c.stf.getObjectValue(edt_EDU_DD);
        var REMK = $c.stf.getObjectValue(txa_REMK);
        var vHeadString = "LIST_APPLNT_ISUR_CD:STRING(5),";
        vHeadString += "CHRG_TP_CD:STRING(2),";
        vHeadString += "CHRG_NM:STRING(80),";
        vHeadString += "EDU_DD:STRING(8),";
        vHeadString += "REMK:STRING(2000)";
        //dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_Item.insertRow();
        dts_Item.setCellData(1, "LIST_APPLNT_ISUR_CD", ISUR_CD);
        dts_Item.setCellData(1, "CHRG_TP_CD", CHRG_TP_CD);
        dts_Item.setCellData(1, "CHRG_NM", CHRG_NM);
        dts_Item.setCellData(1, "EDU_DD", EDU_DD);
        dts_Item.setCellData(1, "REMK", REMK);
        scwin.procJob = "저장";
        scwin.fn_trs(TR_JOB_INSERT);
    }
};



/**
 * 수정버튼 클릭
 */
scwin.fn_modify = function() {
    if (scwin.fn_validation()) {
        if (!$c.lcd.fn_isProcess(scwin.vMode)) return;
        scwin.procJob = "수정";
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};



/**
 * 삭제버튼 클릭
 */
scwin.fn_delete = function() {
    scwin.vMode = "D";
    if (!$c.lcd.fn_isProcess("D")) return;
    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_validation = function() {
    //상장신청인(명)
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("상장신청인(명)은 필수입니다.");
        return false;
    }

    //담당자구분
    if ($c.stf.getObjectValue(cmb_CHRG_TP_CD) == "") {
        $c.win.alert("담당자 구분값은 필수입니다.");
        return false;
    }

    //성명
    if ($c.stf.getObjectValue(cmb_CHRG_NM) == "") {
        $c.win.alert("담당자 성명은 필수입니다.");
        return false;
    }

    //교육일자
    if ($c.stf.getObjectValue(edt_EDU_DD) == "") {
        $c.win.alert("교육일자는 필수입니다.");
        return false;
    }

    //비고 
    if ($c.stf.getObjectValue(txa_REMK) == "") {
        $c.win.alert("비고란 입력은 필수입니다.");
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "비고")) return false;
    return true;
};


/**
 * 저장 및 수정 시 
 * 트랜잭션 정보 설정
 */
scwin.fn_trs = function(trsIdx) {
    if (scwin.vMode == 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.vMode == 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.vMode == 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    if (scwin.vMode == "I" || scwin.vMode == "U") {
        //교육이수현황 추가/수정
        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalSupport.do?method=saveEduCompltStat&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD);
    } else {
        //교육이수현황 삭제
        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalSupport.do?method=deleteEduCompltStat&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD);
    }
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item, I:pFile=dts_fileList)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo;
    trs_Save.Post();
};
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_file_sync = function() {
    var url = "";
    url = "/digital/DigitalListedRcv.do?method=readEtnFileReceipt&inputMessageId=ETN_ATTACH_FILE_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.Reset();
};


/********************************************** 
 * 함수명 : fn_filedown(bzProcsNo, attachFileNo) 
 * Params : bzProcsNo:업무처리번호 , attachFileNo: 번호
 * 설명    : 파일 다운로드 (gubun = 311)
 ***********************************************/
scwin.fn_filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};


/********************************************** 
 * 함수명 : fn_SetParIsur2()
 * 설명    : 상장신청인 선택 팝업호출용
 **********************************************/
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
    }

    //성명셋팅
    scwin.fn_setChrgNM();
};
scwin.fn_GetParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};


/**
 * 교육이수현황  리스트 재조회
 */
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.gform_onload = function() {
    //부모창에서 클릭된 로우 코드 
    var parentWin = $c.frame.path("../");
    scwin.vMode = parentWin.scwin.vMode;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;

    //버튼 셋팅
    scwin.setButton();

    //담당자구분 코드 셋팅
    scwin.fn_searchCode();

    //오늘날짜 셋팅
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_EDU_DD.setValue(vCurDate);

    //첨부파일 조회
    scwin.fn_file_sync();
    if (scwin.vMode == "U") {
        //교육이수현황 조회 
        scwin.fn_list_sync();

        //성명셋팅
        scwin.fn_setChrgNM();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_modify_onclick = function() {
    scwin.fn_modify();
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.cmb_CHRG_TP_CD_OnSelChange = function() {
    scwin.fn_setChrgNM();
};
scwin.btn_FileDelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.grd_fielList_OnDblClick = function(row, colid) {
    // 파일다운로드	
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.dn.fn_filedown(scwin.vBzProcsNo, dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.btn_file_onclick = function() {
    if (dts_fileList.getTotalRow() == 10) {
        $c.win.alert("첨부파일은 최대 10개 입니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        //확장자 확인
        if (!$c.lcd.checkBadExt(inf_find.getValue())) {
            $c.win.alert("해당파일은 첨부할 수 없습니다.");
            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
            inf_find.setValue("");
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileUrl", inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        return;
    }
    inf_find.setValue("");
};
scwin.img_IsuSearch_onclick = function() {
    scwin.fn_SetPar = fn_SetParIsur2;
    scwin.fn_GetPar = fn_GetParIsur2;
    $c.lcd.fn_PopFindDigitalIsurAppl();
};
scwin.img_EDU_DD_onclick = function() {
    popUpCalendar2(edt_EDU_DD);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
